var app = WebApplication.CreateBuilder(args).Build();

app.MapPost("/auth/external",
    async (TokenLogin body, IHttpClientFactory factory, Users users) =>
{
    // Any access token from this provider passes, whichever app it was for
    var http = factory.CreateClient();
    http.DefaultRequestHeaders.Authorization = new("Bearer", body.Token);
    var profile = await http.GetFromJsonAsync<Profile>(
        "https://id.example.com/userinfo");
    return profile is null
        ? Results.Unauthorized()
        : Results.Ok(await users.SignInByEmailAsync(profile.Email));
});
app.Run();

using Microsoft.IdentityModel.JsonWebTokens;
using Microsoft.IdentityModel.Protocols;
using Microsoft.IdentityModel.Protocols.OpenIdConnect;
using Microsoft.IdentityModel.Tokens;

var app = WebApplication.CreateBuilder(args).Build();
const string Issuer = "https://id.example.com";
var metadata = new ConfigurationManager<OpenIdConnectConfiguration>(
    $"{Issuer}/.well-known/openid-configuration",
    new OpenIdConnectConfigurationRetriever());

app.MapPost("/auth/external", async (TokenLogin body, Users users) =>
{
    var result = await new JsonWebTokenHandler().ValidateTokenAsync(body.Token,
        new TokenValidationParameters
        {
            ConfigurationManager = metadata, // the issuer's signing keys
            ValidIssuer = Issuer,
            ValidAudience = "shop-mobile",   // our client_id
        });
    if (!result.IsValid) return Results.Unauthorized();
    var subject = (string)result.Claims["sub"];
    return Results.Ok(await users.SignInAsync(Issuer, subject));
});
app.Run();
